func take_hit(_shell: Node = null) -> void:
	if stage >= 2:
		return
	hits += 1
	var new_stage := 2 if hits >= HITS_TO_BREAK else (1 if hits >= HITS_TO_CRACK else 0)
	if world:
		world.audio.play("cover_hit")
		world.spawn_fx("debris", global_position + Vector2(0, -8))
	if new_stage != stage:
		stage = new_stage
		sprite.texture = _tex[stage]
		if stage == 2:
			shape.set_deferred("disabled", true)

func _update_damage_look() -> void:
	var r := float(health) / float(max_health)
	smoke.emitting = r <= 0.6
	flames.emitting = r <= 0.3

func _update_hud() -> void:
	if health_bar == null:
		return
	health_bar.value = player.health
	var r := float(player.health) / float(player.max_health)
	_hp_fill.bg_color = Color(0.3, 0.8, 0.3) if r > 0.6 else (Color(0.95, 0.75, 0.2) if r > 0.3 else Color(0.9, 0.25, 0.2))
	enemies_label.text = "Enemy tanks left: %d" % remaining
